import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.B0lbOe_c.js";var o=JSON.parse(`{"title":"Metamodell-Pakete","description":"","frontmatter":{"title":"Metamodell-Pakete","covers":{"screens":[],"stories":["US-033","US-057","US-063","US-064","US-075","US-076","US-083"]}},"headers":[],"relativePath":"de/administration/metamodel-packages.md","filePath":"de/administration/metamodel-packages.md"}`),s={name:`de/administration/metamodel-packages.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="metamodell-pakete" tabindex="-1">Metamodell-Pakete <a class="header-anchor" href="#metamodell-pakete" aria-label="Permalink to “Metamodell-Pakete”">​</a></h1><p>Eine neue Instanz hat keine Entitätstypen. Bevor jemand Entitäten erfassen kann, importierst du ein Metamodell: das mitgelieferte Starterpaket oder ein eigenes Paket.</p><p>Der Import von Paketen verlangt die Berechtigung <code>metamodel:write</code>, die nur die Rolle <code>metamodel-admin</code> hat – nicht das lokale Systemadmin-Konto. Ordne eine IdP-Gruppe <code>metamodel-admin</code> zu (siehe <a href="./roles-and-permissions">Rollen und Berechtigungen</a>); als privilegierte Rolle braucht sie einen zweiten Faktor beim Identity-Provider.</p><h2 id="starterkonfiguration-importieren" tabindex="-1">Starterkonfiguration importieren <a class="header-anchor" href="#starterkonfiguration-importieren" aria-label="Permalink to “Starterkonfiguration importieren”">​</a></h2><p>OEA liefert das Starterpaket <code>oea-starter-togaf-classic</code> mit den Entitätstypen Application Component, Application Service, Data Object, Technology Component, Technology Service, System Software und Network Node, jeweils mit der Eigenschaft <em>Status</em>. Version 1.5.0 fügt die Typen der Datenherkunft hinzu (siehe <a href="#lineage-types">Lineage-Typen</a>). Version 1.4.0 fügt die vier <a href="./metamodel-editing#layers">Schichten</a> <em>Geschäft</em>, <em>Daten</em>, <em>Anwendung</em> und <em>Technologie</em> (englisch <em>Business</em>, <em>Data</em>, <em>Application</em> und <em>Technology</em>) hinzu und ordnet sie den Entitätstypen zu: <em>Application Component</em> und <em>Application Service</em> der Schicht Anwendung, <em>Data Object</em> der Schicht Daten und <em>Technology Component</em>, <em>Technology Service</em>, <em>System Software</em> und <em>Network Node</em> der Schicht Technologie (<em>Komposition</em> hat keine). Der erneute Import in eine Instanz mit einer eigenen Schicht desselben Namens, zum Beispiel <em>Business</em>, wird als Konflikt abgelehnt; benenne diese Schicht zuerst um oder lösche sie. Version 1.3.0 fügt den Verbindungstyp <em>Komposition</em> hinzu, gekennzeichnet als <a href="./metamodel-editing#composition">Komposition</a> der Hierarchie von Komponenten. Version 1.2.0 fügt die zwei systemdefinierten Viewpoints <em>Application Landscape</em> und <em>Technology Landscape</em> in ArchiMate hinzu (siehe <a href="#viewpoints-in-packages">Viewpoints in Paketen</a>). Version 1.1.0 brachte deutsche Labels für seine Entitätstypen, <em>Status</em> und dessen Werte sowie englische Labels für die Werte mit (siehe <a href="./metamodel-editing#translating-labels">Labels übersetzen</a>). Eine Instanz, die eine frühere Version importiert hat, erhält die Labels und Viewpoints durch einen erneuten Import des Pakets.</p><p>Neben dem TOGAF-Paket liefert OEA das Starterpaket <code>oea-starter-bpmn</code> (siehe <a href="#bpmn-package">Das BPMN-Starterpaket</a>). Solange die Instanz keinen Entitätstyp hat, zeigt die Startseite einer Person mit <code>metamodel:write</code> den Bereich <em>Startkonfiguration importieren</em>. Wähle <em>Importieren</em> neben dem Paket; die Seite bestätigt, wie viele Entitätstypen jetzt verfügbar sind.</p>`,6),i(d,{name:`starter-import`,alt:`Startseite mit der Starterkonfiguration zum Import`}),o[1]||=t('<p>Über die API:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/starter-packages&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                    # Liste mit Zusammenfassung</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/starter-packages/oea-starter-togaf-classic/import&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/metamodel/metatypes&quot;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                                       # importierte Entitätstypen</span></span></code></pre></div><h2 id="starter-packages-section" tabindex="-1">Ein Starterpaket später importieren <a class="header-anchor" href="#starter-packages-section" aria-label="Permalink to “Ein Starterpaket später importieren”">​</a></h2><p>Ein Starterpaket lässt sich auch in eine Instanz importieren, die schon Entitätstypen hat, zum Beispiel das BPMN-Paket neben dem TOGAF-Paket. Wähle in der Kopfzeile <em>Metamodell</em> und den Bereich <em>Starterpakete</em> (für Inhaber von <code>metamodel:write</code>). Er listet die mitgelieferten Pakete mit Name, Version, Beschreibung, der Zahl der Entitätstypen und Eigenschaften und der Angabe, ob das Paket importiert ist, mit der Version des letzten Imports. Wähle <em>Importieren</em> neben einem Paket, das noch nicht importiert ist, und bestätige. Ein Paket, das in einer älteren als der mitgelieferten Version importiert ist, zeigt stattdessen <em>Auf</em> und die ausgelieferte Version <em>aktualisieren</em>, zum Beispiel <em>Auf 1.5.0 aktualisieren</em>: Es importiert die mitgelieferte Version mit der Strategie <code>merge</code>, ergänzt den neuen Inhalt und behält die IDs der vorhandenen Typen und des Viewpoints, sodass Diagramme, Layouts und Entitäten unverändert bleiben und keine Konflikte erhalten. Die Seite zeigt danach, wie viele Elemente angelegt wurden; die Entitätstypen erscheinen sofort im Metamodell. Ist ein Name des Pakets schon vergeben, von deiner Organisation oder von einem anderen Paket, wird nichts importiert, und der Bereich listet die kollidierenden Namen; benenne dein eigenes Element um oder lösche es und versuche es erneut. Der Bereich ist auch bei <a href="./metamodel-editing#lock-mode">gesperrtem</a> Metamodell verfügbar, wie jeder Paketimport.</p><h2 id="lineage-types" tabindex="-1">Lineage-Typen im TOGAF-Paket <a class="header-anchor" href="#lineage-types" aria-label="Permalink to “Lineage-Typen im TOGAF-Paket”">​</a></h2><p>Version 1.5.0 von <code>oea-starter-togaf-classic</code> ergänzt, was die <a href="./../usage/data-lineage">Datenherkunft</a> braucht; das Paket listet dann zehn Entitäts- und Verbindungstypen:</p><ul><li>den Verbindungstyp <em>Data Flow</em> (Datenfluss) zwischen <em>Application Component</em>, <em>Application Service</em>, <em>Technology Component</em> und <em>System Software</em> (einschließlich ihrer Untertypen), in beide Richtungen, mit den optionalen Eigenschaften <em>Protocol</em> (<code>REST</code>, <code>SOAP</code>, <code>JDBC</code>, <code>FTP</code>, <code>Kafka</code>, <code>SFTP</code>, <code>other</code>), <em>Frequency</em> (<code>realtime</code>, <code>hourly</code>, <code>daily</code>, <code>weekly</code>, <code>on-demand</code>), <em>Personal data categories</em> (bis zu 500 Zeichen) und <em>Transformation description</em> (bis zu 1000 Zeichen);</li><li>den Verbindungstyp <em>Carries Data</em> (transportiert Daten) von einem <em>Data Flow</em> zu einem <em>Data Object</em>;</li><li>drei optionale Eigenschaften am <em>Data Object</em>: <em>Data classification</em> (<code>public</code>, <code>internal</code>, <code>confidential</code>, <code>restricted</code>), <em>Personal data categories</em> und <em>Data owner</em> (bis zu 255 Zeichen). Nichts ist verpflichtend, sodass kein vorhandenes Datenobjekt unvollständig wird;</li><li><em>Data Flow</em> in den Viewpoints <em>Application Landscape</em> und <em>Technology Landscape</em> (ArchiMate <em>Flow</em>); <em>Carries Data</em> steht in keinem Viewpoint;</li><li>deutsche Labels und den Abschnitt <code>lineageModel</code>, der das <a href="./metamodel-editing#lineage-model">Lineage-Modell</a> mit <em>Data Object</em>, <em>Data Flow</em> und <em>Carries Data</em> füllt.</li></ul><p><strong>Namen:</strong> Hat deine Organisation einen eigenen Entitäts- oder Verbindungstyp <em>Data Flow</em> oder <em>Carries Data</em> oder eine eigene Eigenschaft <em>Protocol</em> oder <em>Frequency</em>, wird die Aktualisierung auf 1.5.0 mit <code>409</code> abgelehnt und nichts importiert, weil Inhalte anderer nie überschrieben werden. Benenne dein eigenes Element zuerst um und aktualisiere dann. Die Aktualisierung behält alle Entitäten, Werte und Diagramme.</p><p>Das BPMN-Paket 1.2.0 bringt keine neuen Typen; sein Abschnitt <code>lineageModel</code> nennt die <em>Data Input Association</em> und die <em>Data Output Association</em> als Dateneingabe und Datenausgabe.</p><p>Ein eigenes Paket kann die Teile genauso mit <code>lineageModel</code> füllen: je Teil die ID eines Entitätstyps des Pakets (<em>dataObject</em>) oder eines Verbindungstyps (<em>dataFlow</em>, <em>carriesData</em>, <em>dataInput</em>, <em>dataOutput</em>); ein anderer Typ oder einer der falschen Art antwortet mit <code>422</code> und nennt <code>/lineageModel/&lt;Teil&gt;</code>. Der Import füllt nur Teile, die nicht gesetzt sind, listet sie in <code>lineageModelFilled</code> und protokolliert sie als <code>metamodel.lineage-model-updated</code> mit <code>cause: package-import</code>.</p><h2 id="bpmn-package" tabindex="-1">Das BPMN-Starterpaket <a class="header-anchor" href="#bpmn-package" aria-label="Permalink to “Das BPMN-Starterpaket”">​</a></h2><p>Das Paket <code>oea-starter-bpmn</code> (<em>BPMN 2.0 process modeling</em>) bringt die Typen von Geschäftsprozessmodellen:</p><ul><li>28 Entitätstypen: das <em>BPMN Data Object</em> (mit der optionalen Eigenschaft <em>Collection</em>) und der <em>BPMN Data Store</em> (siehe <a href="./../usage/diagrams#data-objects">Datenobjekte und Datenspeicher</a>), <em>Process</em>, <em>Pool</em>, <em>Lane</em>, die Aktivitäten <em>Task</em>, <em>User Task</em>, <em>Service Task</em>, <em>Send Task</em>, <em>Receive Task</em>, <em>Business Rule Task</em>, <em>Script Task</em>, <em>Sub-Process</em> und <em>Call Activity</em>, die Ereignisse <em>Start Event</em>, <em>Message Start Event</em>, <em>Timer Start Event</em>, <em>End Event</em>, <em>Message End Event</em>, <em>Terminate End Event</em>, <em>Intermediate Catch Event</em> und <em>Intermediate Throw Event</em>, die Gateways <em>Exclusive Gateway</em>, <em>Parallel Gateway</em>, <em>Inclusive Gateway</em> und <em>Event-Based Gateway</em> sowie die Artefakte <em>Text Annotation</em> und <em>Group</em>. Die Aufgabenvarianten haben den Basistyp <em>Task</em>, die Startereignis-Varianten <em>Start Event</em> und die Endereignis-Varianten <em>End Event</em>, sodass eine Regel für <em>Task</em> auch <em>User Task</em> und die Untertypen deiner Organisation umfasst.</li><li>die Verbindungstypen <em>Sequence Flow</em>, <em>Message Flow</em>, <em>Association</em> (von einer Textanmerkung aus), <em>Calls</em> (von einer Aufrufaktivität zu einem Prozess) und <em>References Process</em> (von einem Pool zu einem Prozess), jeweils auf BPMN-Elemente als Quelle und Ziel beschränkt; die <em>Data Input Association</em> (von jedem Entitätstyp zu einer Aufgabe) und die <em>Data Output Association</em> (von einer Aufgabe zu jedem Entitätstyp), deren offene Enden das TOGAF-<em>Data Object</em> ohne Abhängigkeit zwischen den Paketen teilnehmen lassen, mit den Eigenschaften <em>Transformation type</em> (<code>create</code>, <code>enrich</code>, <code>overwrite</code>, <code>delete</code>, <code>read-only</code>), <em>Affected attributes</em> (bis zu 5049 Zeichen, eines pro Zeile) und <em>Condition</em> (bis zu 2000 Zeichen) an der Ausgabeassoziation; und <em>Realized By</em> (von jedem Entitätstyp zu jedem Entitätstyp, zum Beispiel von einem Datenspeicher zu einer <em>System Software</em>). Die Eigenschaften des Pakets sind <em>Association direction</em> (<code>none</code>, <code>one</code>, <code>both</code>), <em>Group category</em> (bis zu 255 Zeichen), <em>Collection</em>, <em>Transformation type</em>, <em>Affected attributes</em> und <em>Condition</em>;</li><li>deutsche Bezeichnungen für alle diese Elemente und der systemdefinierte Viewpoint <em>Process Model (BPMN 2.0)</em> mit der Notation BPMN 2.0, allen diesen Typen, BPMN-Symbolen und Standardgrößen. Der Viewpoint behält in jeder Sprache seinen englischen Namen.</li></ul><p><strong>Was das Paket auslässt:</strong> Organisationseinheiten, Rollen und die <a href="./../usage/diagrams#assignments">Zuordnung von Bahnen</a> kommen mit dem <a href="#organization-package">Organisations-Paket</a>. Version 1.2.0 ergänzt den Abschnitt <code>lineageModel</code>; Version 1.1.0 hat die Datentypen ergänzt; Version 1.0.0 hatte keine. Der Viewpoint des Pakets ist schreibgeschützt: Um das TOGAF-<em>Data Object</em> als Datenobjekt zu zeichnen, lege einen Viewpoint der Notation BPMN 2.0 an, der es erlaubt (siehe <a href="./../usage/diagrams#data-objects">Datenobjekte und Datenspeicher</a>). <strong>Einschluss ist die Hierarchie der Entitäten:</strong> Eine Bahn ist Kind ihres Pools, eine Aufgabe Kind ihrer Bahn; das Paket definiert keine Kompositionsverbindung, sodass mit diesem Paket allein für die Hierarchie keine Verbindung angelegt wird. Ist das TOGAF-Paket importiert, wird seine Verbindung <em>Composition</em> wie bei anderen Entitäten angelegt. Die Typen sind importierte Typen wie jede andere: schreibgeschützt, aber du kannst Eigenschaften und Untertypen hinzufügen. Importiere das Paket über die Startseite oder über den Bereich <em>Starterpakete</em>; dieses Paket und das TOGAF-Paket lassen sich in beliebiger Reihenfolge importieren.</p><p>Über die API ist die Liste der Pakete nach <code>packageId</code> sortiert; suche ein Paket daher über seine Kennung, nicht über seine Position.</p><h2 id="organization-package" tabindex="-1">Das Organisations-Starterpaket <a class="header-anchor" href="#organization-package" aria-label="Permalink to “Das Organisations-Starterpaket”">​</a></h2><p>Das Paket <code>oea-starter-organization</code> (<em>Organisationsmodell</em>) benennt, wer ausführt und wer verantwortlich ist, in einem BPMN-Diagramm und für jedes Architekturobjekt:</p><ul><li>die Entitätstypen <em>Organizational Unit</em>, <em>Role</em> und <em>Person</em> (die Eigenschaft <em>Account ID</em> der Person hat bis zu 255 Zeichen; sie ist die Eigenschaft, <a href="./property-visibility#account-mapping">die ein Konto mit der Person verknüpft</a>) und die Verbindungstypen <em>Belongs To</em> (zu einer Organisationseinheit), <em>Performs Role</em> (zu einer Rolle) und <em>Responsible</em> (zu einer Person), jeweils von <strong>jedem</strong> Entitätstyp aus – einer Bahn, einer <em>Application Component</em> oder einem anderen –, sodass das Paket weder das BPMN- noch das TOGAF-Paket braucht. <em>Responsible</em> nennt nur Personen, keine Rollen oder Organisationseinheiten. Die Hierarchie der Organisationseinheiten ist die Hierarchie der Entitäten;</li><li>deutsche Labels, keinen Viewpoint;</li><li>den Abschnitt <code>organizationModel</code>, der das <a href="./metamodel-editing#organization-model">Organisationsmodell</a> der Instanz füllt: Der Import setzt die sechs Teile, die noch nicht gesetzt sind, und überschreibt nie einen gesetzten Teil. Das Importergebnis listet sie in <code>organizationModelFilled</code>, und ein Audit-Ereignis <code>metamodel.organization-model-updated</code> mit <code>cause: package-import</code> hält sie fest.</li></ul><p>Das Paket lässt sich allein oder neben den anderen Paketen importieren. Ein eigenes Paket kann die Teile genauso mit <code>organizationModel</code> füllen: je Teil die ID eines Entitätstyps des Pakets (<em>orgUnit</em>, <em>role</em>, <em>person</em>) oder eines Verbindungstyps (<em>belongsTo</em>, <em>performsRole</em>, <em>responsible</em>); ein anderer Typ oder einer der falschen Art antwortet mit <code>422</code> und nennt <code>/organizationModel/&lt;Teil&gt;</code>.</p><h2 id="eigenes-paket-importieren" tabindex="-1">Eigenes Paket importieren <a class="header-anchor" href="#eigenes-paket-importieren" aria-label="Permalink to “Eigenes Paket importieren”">​</a></h2><p>Eigene Pakete verwenden dasselbe JSON-Format (<code>MetamodelPackage</code>, mit <code>packageId</code>, <code>packageVersion</code>, <code>publisher</code> und stabilen UUIDs pro Element). Importiere sie mit <code>POST /metamodel/import</code>:</p><ul><li>Ein Paket wird vollständig oder gar nicht importiert. Importierte Inhalte bekommen den Scope <code>imported</code> und das Paket als Herkunft.</li><li>Ein erneuter Import desselben Pakets aktualisiert dessen eigene Inhalte. Inhalte eines anderen Pakets oder deiner Organisation werden nie überschrieben; die Antwort ist <code>409</code> mit dem Problemtyp <code>urn:oea:problem:package-conflict</code> und der Liste der Konflikte in <code>conflictList</code>, und nichts vom Paket wird gespeichert.</li><li>Ein Paket kann für einen Entitätstyp einen Basistyp nennen (<code>baseMetatypeId</code>): einen Entitätstyp desselben Pakets oder einen eingebauten. Deine eigenen Eigenschaften an seinen Entitätstypen bleiben oder werden entfernt, je nach Einstellung für den erneuten Import (siehe <a href="./metamodel-editing">Metamodell bearbeiten</a>).</li><li>Pakete, die größer als <code>oea.metamodel.import.max-size</code> sind (Standard 10 MB), werden mit <code>413</code> abgelehnt; fehlerhaftes JSON oder Inhalte, die nicht zum Format passen, mit <code>422</code> und der Stelle des Problems.</li><li>Ein Paket kann in <code>i18nBundles</code> Labels pro Sprache mitbringen, mit Schlüsseln wie unter <a href="./metamodel-editing#translating-labels">Labels übersetzen</a>, aber nur für seine eigenen Elemente. Ein erneuter Import ersetzt sie; deine eigenen Labels bleiben.</li><li>Die Strategie <code>replace</code> und Shape-Zuordnungen werden noch nicht unterstützt (<code>422</code>).</li></ul><p>Jeder Import schreibt die Audit-Events <code>metamodel.package-imported</code> und <code>metamodel.metatype-imported</code> mit einer gemeinsamen Batch-ID.</p><h2 id="composition-in-packages" tabindex="-1">Komposition in Paketen <a class="header-anchor" href="#composition-in-packages" aria-label="Permalink to “Komposition in Paketen”">​</a></h2><p>Ein Verbindungstyp eines Pakets kann <code>isComposition: true</code> tragen; ein Paket hat höchstens einen. Der Import wird abgelehnt, wenn die Instanz bereits einen anderen gekennzeichneten Verbindungstyp hat. Ein erneuter Import desselben Pakets verschiebt oder entfernt die Kennzeichnung mit dem Paket.</p><h2 id="layers-in-packages" tabindex="-1">Schichten in Paketen <a class="header-anchor" href="#layers-in-packages" aria-label="Permalink to “Schichten in Paketen”">​</a></h2><p>Ein Paket kann in <code>architectureLayers</code> Architekturschichten mitbringen: jede mit einer stabilen <code>id</code>, einem <code>name</code> mit bis zu 100 Zeichen und einer optionalen <code>sortOrder</code>. Die Entitätstypen des Pakets verweisen mit <code>architectureLayerId</code> darauf. Der Import installiert sie als schreibgeschützte Schichten mit dem Paket als Herkunft (siehe <a href="./metamodel-editing#layers">Schichten</a>).</p><ul><li>Ein Paket hat höchstens 20 Schichten, und zusammen mit den Schichten deiner Organisation hat die Instanz höchstens 20 (sonst <code>422</code>). Namen sind im Paket unabhängig von der Schreibweise eindeutig; ein Entitätstyp, der auf eine Schicht ausserhalb des Pakets verweist, wird mit <code>422</code> abgelehnt.</li><li>Eine Schicht, deren ID oder Name zu einer Schicht deiner Organisation oder eines anderen Pakets gehört, ergibt <code>409</code> mit <code>package-conflict</code>, und nichts wird importiert.</li><li>Neue Schichten stehen hinter den vorhandenen, in der Reihenfolge von <code>sortOrder</code>; vorhandene Schichten behalten ihre Position.</li><li>Ein erneuter Import desselben Pakets aktualisiert seine Schichten. Eine Schicht, die die neue Version nicht mehr hat, wird gelöscht, und jeder Entitätstyp, der sie hatte – auch die deiner Organisation –, verliert seine Schicht. Schichten deiner Organisation bleiben.</li><li>Das Importergebnis zählt die angelegten, aktualisierten und gelöschten Schichten (<code>layersCreated</code>, <code>layersUpdated</code>, <code>layersDeleted</code>) und die Entitätstypen, die eine Schicht verloren haben (<code>layerAssignmentsCleared</code>). Labels für eine Schicht stehen in <code>i18nBundles</code> unter dem Schlüssel <code>architecture-layer.{id}.name</code>.</li></ul><h2 id="viewpoints-in-packages" tabindex="-1">Viewpoints in Paketen <a class="header-anchor" href="#viewpoints-in-packages" aria-label="Permalink to “Viewpoints in Paketen”">​</a></h2><p>Ein Paket kann in <code>viewpoints</code> Viewpoints mitbringen: jeden mit einer stabilen <code>id</code>, <code>name</code>, optionaler <code>description</code>, <code>notation</code>, den erlaubten <code>metatypeIds</code> und <code>connectionTypeIds</code> (Typen des Pakets oder der Instanz), optionalen <code>mappings</code> und optionalen Standardgrössen <code>sizes</code> in pt (<code>metatypeId</code> mit <code>width</code> und <code>height</code> oder <code>length</code>; siehe <a href="./metamodel-editing#viewpoints">Viewpoints</a>) und dem optionalen <code>askNewParent</code> (<code>true</code> oder <code>false</code>; ohne Angabe gilt die globale Einstellung). Der Import installiert sie als systemdefinierte, schreibgeschützte Viewpoints mit dem Paket als Herkunft (siehe <a href="./metamodel-editing#viewpoints">Viewpoints</a>).</p><ul><li>Ein Viewpoint hat dieselben Grenzen wie ein eigener: Name bis 255 Zeichen, Beschreibung bis 1000, höchstens 500 Entitätstypen, 500 Verbindungstypen, 1000 Zuordnungen und 1000 Grössen, Grössen von 1 bis 2000 pt und Farben als <code>#rrggbb</code>. Ein Verstoss oder ein unbekannter Typ wird mit <code>422</code> abgelehnt und nennt den Viewpoint, eine fehlerhafte Grösse auch <code>sizes</code>. <code>defaultWidth</code> und <code>defaultHeight</code> in einer Zuordnung werden ignoriert.</li><li>Ein erneuter Import desselben Pakets aktualisiert seine Viewpoints, auch wenn einer umbenannt wurde, und löscht die, die das Paket nicht mehr enthält, samt ihren <a href="./../usage/diagrams">Diagrammen</a>, auch den gelöschten; die Entitäten bleiben. Viewpoints deiner Organisation oder eines anderen Pakets werden nie überschrieben: Dieselbe ID oder derselbe Name ergibt <code>409</code>.</li><li>Das Importergebnis zählt die angelegten, aktualisierten und gelöschten Viewpoints und, als <code>diagramsDeleted</code>, die Diagramme, die mit ihnen gelöscht wurden. Ein abgelehnter Import löscht nichts.</li></ul>',31)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};